// Runtime helpers for pages generated by DeckGL.jl.
//
// The Julia side emits plain JavaScript -- `new deck.ScatterplotLayer({...})` -- so
// there is no spec language to interpret here. What is left is decoding the binary
// buffers, formatting tooltips, and wiring deck.gl to an optional basemap.
const DG = {
    // Layer attributes arrive base64-encoded and are adopted as typed arrays without
    // a copy, which is the whole point of sending them this way.
    u8(s) {
        if (Uint8Array.fromBase64) return Uint8Array.fromBase64(s);
        const bin = atob(s);
        const out = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
        return out;
    },
    f32(s) { return new Float32Array(DG.u8(s).buffer); },

    // Aggregation layers need iterable data. Indices stand in for records, and the
    // accessors below read the packed buffers at that index.
    range(n) { return Array.from({length: n}, (_, i) => i); },
    at(buf, size) {
        return size === 1 ? i => buf[i] : i => buf.subarray(i * size, i * size + size);
    },

    escape(v) {
        return String(v).replace(/[&<>"]/g, c => ({"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"}[c]));
    },

    // Binary data has no row objects, so picking reports an index and the tooltip
    // columns are looked up by it.
    tooltip(tables) {
        return info => {
            const table = info.layer && tables[info.layer.id];
            if (!table || info.index < 0) return null;
            // Aggregated bins describe themselves; everything else is looked up by index.
            const entries = table.object
                ? Object.entries(info.object || {}).filter(([, v]) => v === null || typeof v !== "object")
                : table.keys.map((key, i) => [key, table.cols[i][info.index]]);
            if (!entries.length) return null;
            return {html: entries.map(([k, v]) => `<b>${DG.escape(k)}</b>: ${DG.escape(v)}`).join("<br>")};
        };
    },

    mount(spec) {
        const props = Object.assign({canvas: "deck-canvas"}, spec.deck);

        if (spec.mapStyle) {
            const view = props.initialViewState || {};
            const map = new maplibregl.Map({
                container: "map",
                style: spec.mapStyle,
                center: [view.longitude || 0, view.latitude || 0],
                zoom: view.zoom || 1,
                pitch: view.pitch || 0,
                bearing: view.bearing || 0,
                interactive: false,
            });

            // deck.gl owns the camera; the basemap follows it. Chain rather than
            // replace, so a user-supplied onViewStateChange still runs.
            const chained = props.onViewStateChange;
            props.onViewStateChange = event => {
                const v = event.viewState;
                map.jumpTo({
                    center: [v.longitude, v.latitude],
                    zoom: v.zoom,
                    pitch: v.pitch || 0,
                    bearing: v.bearing || 0,
                });
                return chained ? chained(event) : undefined;
            };
        } else {
            document.getElementById("map").remove();
        }

        // `deck.Deck`, not `deck.DeckGL`: the latter is a scripting wrapper that creates
        // its own canvas and -- finding `globalThis.maplibregl`, which a basemap page
        // loads -- its own second basemap, both appended to `<body>` above this
        // container, where they swallow every pointer event. We supply the canvas and
        // the basemap ourselves.
        return (DG.instance = new deck.Deck(props));
    },
};
